def _close_to_identity(expr, identity, rtol, atol):
    # Check whether a number is close enough to the additive or
    # multiplicative identity to be ignored e.g. a term that is
    # approximately zero in a sum.
    return (isinstance(expr, NUM_TYPES) and
            bool(abs(expr - identity) <= atol + rtol*abs(identity)))

def _all_close_ac(expr1, expr2, rtol, atol):
    # Compare expressions with associative commutative operators for
    # approximate equality. This could be horribly inefficient for large
    # expressions e.g. an Add with many terms.
    #
    # Any unmatched terms or factors are allowed if they are close to
    # the identity for the operation e.g. a term that is approximately
    # zero in a sum or a factor that is approximately one in a product.
    if expr1.is_Add:
        identity = S.Zero
    else:
        identity = S.One
    if expr2.func == expr1.func:
        args2 = list(expr2.args)
    else:
        args2 = [expr2]
    for arg1 in expr1.args:
        for i, arg2 in enumerate(args2):
            if _all_close(arg1, arg2, rtol, atol):
                args2.pop(i)
                break
        else:
            if not _close_to_identity(arg1, identity, rtol, atol):
                return False
    return all(_close_to_identity(arg2, identity, rtol, atol)
               for arg2 in args2)
